import os
from typing import Any, Dict, List, Optional


def detect_text_in_image(image_path: str) -> Dict[str, Any]:
    """
    Detect text appearing inside an image using Google Cloud Vision.
    Returns a structured result containing full text and per-block detections.
    """
    from google.cloud import vision

    client = vision.ImageAnnotatorClient()

    with open(image_path, "rb") as f:
        content = f.read()

    image = vision.Image(content=content)
    response = client.text_detection(image=image)

    if response.error.message:
        raise RuntimeError(response.error.message)

    annotations = response.text_annotations or []
    full_text = annotations[0].description if annotations else ""

    words: List[Dict[str, Any]] = []
    for ann in annotations[1:]:
        vertices = []
        if ann.bounding_poly and ann.bounding_poly.vertices:
            for v in ann.bounding_poly.vertices:
                vertices.append({"x": v.x, "y": v.y})
        words.append(
            {
                "text": ann.description,
                "bounding_poly": vertices,
            }
        )

    return {
        "full_text": full_text,
        "words": words,
    }
